package hvac_visibility_priority_supervisor.HVAC_Visibility_Priority_Supervisor

import org.sireum._
import art.Art
import hvac_visibility_priority_supervisor._

// Do not edit this file as it will be overwritten if HAMR codegen is rerun
@msig trait CabinAirServiceProposer_supervision_cabinAirServiceProposer_TestApi {

  def BeforeEntrypoint(): Unit = {
    Art.initTest(Arch.HVACSupervisor_Instance_supervision_cabinAirServiceProposer)
  }

  def AfterEntrypoint(): Unit = {
    Art.finalizeTest(Arch.HVACSupervisor_Instance_supervision_cabinAirServiceProposer)
  }

  def testCompute(): Unit = {
    Art.manuallyClearOutput()
    Art.testCompute(Arch.HVACSupervisor_Instance_supervision_cabinAirServiceProposer)
  }

  def testInitialise(): Unit = {
    Art.manuallyClearOutput()
    Art.testInitialise(Arch.HVACSupervisor_Instance_supervision_cabinAirServiceProposer)
  }

  /** helper function to set the values of all input ports.
   * @param humidityNeed payload for data port humidityNeed
   * @param airNeed payload for data port airNeed
   * @param airPath payload for data port airPath
   */
  def put_concrete_inputs(humidityNeed : HVAC_Visibility_Priority_Supervisor.HumidityNeed.Type,
                          airNeed : HVAC_Visibility_Priority_Supervisor.AirNeed.Type,
                          airPath : HVAC_Visibility_Priority_Supervisor.AirPathReadiness): Unit = {
    put_humidityNeed(humidityNeed)
    put_airNeed(airNeed)
    put_airPath(airPath)
  }


  /** helper function to check CabinAirServiceProposer_supervision_cabinAirServiceProposer's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param cabinAirProposal method that will be called with the value of the outgoing data
   *        port 'cabinAirProposal'.
   */
  def check_concrete_output(cabinAirProposal: HVAC_Visibility_Priority_Supervisor.CabinAirProposal => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val cabinAirProposalValue: HVAC_Visibility_Priority_Supervisor.CabinAirProposal = get_cabinAirProposal().get
    if(!cabinAirProposal(cabinAirProposalValue)) {
      testFailures = testFailures :+ st"'cabinAirProposal' did not match expected: value of the outgoing data port is ${cabinAirProposalValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


  // setter for in DataPort
  def put_humidityNeed(value : HVAC_Visibility_Priority_Supervisor.HumidityNeed.Type): Unit = {
    Art.insertInInfrastructurePort(Arch.HVACSupervisor_Instance_supervision_cabinAirServiceProposer.operational_api.humidityNeed_Id, HVAC_Visibility_Priority_Supervisor.HumidityNeed_Payload(value))
  }

  // setter for in DataPort
  def put_airNeed(value : HVAC_Visibility_Priority_Supervisor.AirNeed.Type): Unit = {
    Art.insertInInfrastructurePort(Arch.HVACSupervisor_Instance_supervision_cabinAirServiceProposer.operational_api.airNeed_Id, HVAC_Visibility_Priority_Supervisor.AirNeed_Payload(value))
  }

  // setter for in DataPort
  def put_airPath(value : HVAC_Visibility_Priority_Supervisor.AirPathReadiness): Unit = {
    Art.insertInInfrastructurePort(Arch.HVACSupervisor_Instance_supervision_cabinAirServiceProposer.operational_api.airPath_Id, HVAC_Visibility_Priority_Supervisor.AirPathReadiness_Payload(value))
  }

  // getter for out DataPort
  def get_cabinAirProposal(): Option[HVAC_Visibility_Priority_Supervisor.CabinAirProposal] = {
    val value: Option[HVAC_Visibility_Priority_Supervisor.CabinAirProposal] = get_cabinAirProposal_payload() match {
      case Some(HVAC_Visibility_Priority_Supervisor.CabinAirProposal_Payload(v)) => Some(v)
      case Some(v) => halt(s"Unexpected payload on port cabinAirProposal.  Expecting 'HVAC_Visibility_Priority_Supervisor.CabinAirProposal_Payload' but received ${v}")
      case _ => None[HVAC_Visibility_Priority_Supervisor.CabinAirProposal]()
    }
    return value
  }

  // payload getter for out DataPort
  def get_cabinAirProposal_payload(): Option[HVAC_Visibility_Priority_Supervisor.CabinAirProposal_Payload] = {
    return Art.observeOutInfrastructurePort(Arch.HVACSupervisor_Instance_supervision_cabinAirServiceProposer.initialization_api.cabinAirProposal_Id).asInstanceOf[Option[HVAC_Visibility_Priority_Supervisor.CabinAirProposal_Payload]]
  }

}
